namespace LadderRecords;
class RecordDialog:CompactDialog
{
 readonly Catalog catalog;readonly RecordStore store;readonly string profileId;
 readonly TextBox search=new(){Width=470};readonly ComboBox songs=new ThemedCombo(){Width=470,DropDownWidth=900,DropDownStyle=ComboBoxStyle.DropDownList},buttons=new ThemedCombo(){Width=120,DropDownStyle=ComboBoxStyle.DropDownList},patterns=new ThemedCombo(){Width=150,DropDownStyle=ComboBoxStyle.DropDownList},judges=new ThemedCombo(){Width=120,DropDownStyle=ComboBoxStyle.DropDownList};
 readonly Label existing=new(){AutoSize=true};readonly NumericUpDown value=new(){Minimum=0,Maximum=100,DecimalPlaces=2,Increment=.01m,Width=140},count=new(){Minimum=0,Maximum=int.MaxValue,DecimalPlaces=0,Width=140,ThousandsSeparator=true};bool updating;
 readonly NumericUpDown rawScore=new(){Minimum=0,Maximum=1000000,ThousandsSeparator=true,Width=160};bool syncingScore;
 Score? loaded;   // 이 창에 '현재 등록 점수'로 보여 준 기록. 창이 열려 있는 동안 등록 확인이나 다른 수정으로 바뀔 수 있다
 public int RawScore=>(int)rawScore.Value;public decimal Value=>value.Value;public int PlayCount=>(int)count.Value;
 public Selection Chart=>new(((Song?)songs.SelectedItem??throw new Exception("곡을 선택하세요.")).Id,(int)(buttons.SelectedItem??throw new Exception("버튼을 선택하세요.")),patterns.Text,judges.Text,1);
 public RecordDialog(Catalog catalog,RecordStore store,Selection? initial=null):base("수동 기록 설정"){
  this.catalog=catalog;this.store=store;profileId=store.Active.Id;buttons.FormattingEnabled=true;buttons.Format+=(_,e)=>{if(e.ListItem is int number)e.Value=$"{number}B";};
  Section("곡과 패턴",640);Row("곡 검색",search);Row("곡",songs);Row("버튼 / 난이도 / 판정",buttons,patterns,judges);Section("기록",640);existing.Margin=new(3,6,3,0);existing.Font=Theme.Px("맑은 고딕",10f,FontStyle.Bold);Row("현재 등록 점수",existing);Row("점수 (스코어)",rawScore);Row("점수 (%)",value);Row("플레이 카운트 (회)",count);Buttons("저장");
  judges.Items.AddRange(new object[]{"노말","하드","맥스"});judges.SelectedItem=initial?.Judge??"노말";
  search.TextChanged+=(_,_)=>FilterSongs();songs.SelectedIndexChanged+=(_,_)=>{if(!updating)FillButtons();};buttons.SelectedIndexChanged+=(_,_)=>{if(!updating)FillPatterns();};patterns.SelectedIndexChanged+=(_,_)=>{if(!updating)LoadRecord();};judges.SelectedIndexChanged+=(_,_)=>{if(!updating)LoadRecord();};
  rawScore.ValueChanged+=(_,_)=>{if(syncingScore)return;syncingScore=true;try{value.Value=ScoreValue.Rate((int)rawScore.Value);}finally{syncingScore=false;}};
  value.ValueChanged+=(_,_)=>{if(syncingScore)return;syncingScore=true;try{rawScore.Value=ScoreValue.FromAccuracy(value.Value);}finally{syncingScore=false;}};
  FilterSongs(initial);
  FormClosing+=(_,e)=>{if(DialogResult!=DialogResult.OK)return;try{if(store.Active.Id!=profileId)throw new Exception("프로필이 변경되었습니다. 창을 다시 열어 주세요.");if(!catalog.Songs.Any(s=>s.Id==Chart.SongId&&s.Charts.Contains(new(Chart.Button,Chart.Pattern))))throw new Exception("존재하는 곡과 버튼·난이도를 선택하세요.");var current=store.Get(Chart);if(!Equals(current,loaded)){loaded=current;existing.Text=current==null?"미등록":$"{current.Value:N0} | {current.Accuracy:F2}%";throw new Exception("이 창을 연 뒤에 이 기록이 바뀌었습니다.\n현재 등록 점수를 다시 확인해 주세요.\n입력한 값으로 저장하려면 저장을 한 번 더 누르세요.");}}catch(Exception error){e.Cancel=true;DialogResult=DialogResult.None;NoticeDialog.Show(this,"수동 기록 설정",error.Message);}};
 }
 void FilterSongs(Selection? initial=null){var old=initial?.SongId??(songs.SelectedItem as Song)?.Id;var words=search.Text.Split(' ',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);var found=catalog.Songs.Where(s=>words.All(w=>(s.Name+" "+s.Artist).Contains(w,StringComparison.OrdinalIgnoreCase))).OrderBy(s=>s.Name).ToArray();updating=true;try{songs.Items.Clear();songs.Items.AddRange(found.Cast<object>().ToArray());songs.SelectedItem=found.FirstOrDefault(s=>s.Id==old)??found.FirstOrDefault();}finally{updating=false;}FillButtons(initial);}
 void FillButtons(Selection? initial=null){int? previous=initial?.Button??buttons.SelectedItem as int?;updating=true;try{buttons.Items.Clear();if(songs.SelectedItem is Song song){buttons.Items.AddRange(song.Charts.Select(c=>c.Button).Distinct().OrderBy(b=>b).Cast<object>().ToArray());buttons.SelectedItem=previous.HasValue&&buttons.Items.Contains(previous.Value)?previous.Value:buttons.Items.Cast<object>().FirstOrDefault();}}finally{updating=false;}FillPatterns(initial);}
 void FillPatterns(Selection? initial=null){string previous=initial?.Pattern??patterns.Text;updating=true;try{patterns.Items.Clear();if(songs.SelectedItem is Song song&&buttons.SelectedItem is int button){patterns.Items.AddRange(new[]{"NORMAL","HARD","MAXIMUM","SC"}.Where(p=>song.Charts.Contains(new(button,p))).Cast<object>().ToArray());patterns.SelectedItem=patterns.Items.Contains(previous)?previous:patterns.Items.Cast<object>().FirstOrDefault();}}finally{updating=false;}LoadRecord();}
 void LoadRecord(){bool valid=songs.SelectedItem is Song&&buttons.SelectedItem is int&&patterns.SelectedItem!=null&&judges.SelectedItem!=null;((Button)AcceptButton!).Enabled=valid;if(!valid){existing.Text="검색 결과 없음";value.Value=0;count.Value=0;loaded=null;return;}var old=store.Get(Chart);loaded=old;existing.Text=old==null?"미등록":$"{old.Value:N0} | {old.Accuracy:F2}%";syncingScore=true;try{value.Value=old?.Accuracy??0;rawScore.Value=old?.Value??0;count.Value=old?.PlayCount??0;}finally{syncingScore=false;}}
}
